import numpy as np
arr=np.array(grid)
out=arr.copy()
for r in range(arr.shape[0]):
    cols=np.where(arr[r]==2)[0]
    for a,b in zip(cols,cols[1:]):
        if b>a+1: out[r,a+1:b]=3
for c in range(arr.shape[1]):
    rows=np.where(arr[:,c]==2)[0]
    for a,b in zip(rows,rows[1:]):
        if b>a+1: out[a+1:b,c]=3
assert np.all(out[arr==2]==2)
print('\n'.join(' '.join(map(str,row)) for row in out))
